// @cs-hub-patch:win-exthost v1
// 仅 dsh 模式（监听命名管道）需要：win32 下交给 extHost 的 socket 是管道 socket，
// Node/libuv 不能把管道句柄 child.send() 出去（会 write ENOTSUP）。给出 socket-path 后
// 上游改走自带的管道泵（_listenOnPipe + VSCODE_EXTHOST_IPC_HOOK），全程不传句柄。
if (args.pipe !== null) {
  codeArgs['socket-path'] = process.platform === 'win32'
    ? `\\\\.\\pipe\\dshcs-exthost-${process.pid}`
    : join(userDataDir, `dshcs-exthost-${process.pid}.sock`);
  // 内嵌 IDE 打开的 folder 都是本会话 worktree，不弹 Restricted Mode（契约 §3.4）。
  codeArgs['disable-workspace-trust'] = true;
}
return serverModule.createServer(null, codeArgs);

